/**
 * @method
 * @name bit2c#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://bit2c.co.il/home/api#orderb
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bit2c) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bit2c) fetchOrderBookBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}

	var orderbook map[string]any = MapTyped(PanicOnError((<-this.PublicGetExchangesPairOrderbook(this.Extend(request, params))).Raw))
	// the full orderbook.json snapshot can contain dead orders - rows
	// published with a zero amount at their limit price, hours-stable and
	// sometimes crossing the real market. per the api docs the endpoint
	// contains open orders only, and the venue's own orderbook-top.json ui
	// feed filters these rows out, so a non-positive amount is a dead order
	// their full snapshot failed to purge - it is removed here, which also
	// uncrosses the book. rows are positional price and amount pairs
	var rawBids []any = SafeListTyped(orderbook, "bids")
	var rawAsks []any = SafeListTyped(orderbook, "asks")
	var bids []any = []any{}
	var asks []any = []any{}
	for i := 0; i < len(rawBids); i++ {
		var bidRow any = func() any {
			if i >= 0 && i < len(rawBids) {
				return DerefScalar(rawBids[i])
			}
			return nil
		}()
		var bidAmount *string = this.SafeString(bidRow, 1)
		if Precise.StringGt(bidAmount, "0") {
			bids = append(bids, bidRow)
		}
	}
	for i := 0; i < len(rawAsks); i++ {
		var askRow any = func() any {
			if i >= 0 && i < len(rawAsks) {
				return DerefScalar(rawAsks[i])
			}
			return nil
		}()
		var askAmount *string = this.SafeString(askRow, 1)
		if Precise.StringGt(askAmount, "0") {
			asks = append(asks, askRow)
		}
	}
	var filtered map[string]any = map[string]any{
		"bids": bids,
		"asks": asks,
	}

	ch <- this.ParseOrderBook(filtered, symbol)
	return nil
}
func (this *Bit2c) ParseTicker(ticker any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var symbol *string = this.SafeSymbol(nil, market)
	var averagePrice *string = this.SafeString(ticker, "av")
	var baseVolume *string = this.SafeString(ticker, "a")
	var last *string = this.SafeString(ticker, "ll")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          nil,
		"low":           nil,
		"bid":           this.SafeString(ticker, "h"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "l"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       averagePrice,
		"baseVolume":    baseVolume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

