func (this *Bit2c) ParseOrder(order any, optionalArgs ...any) any {
	//
	//      createOrder
	//      {
	//          "OrderResponse": {"pair": "BtcNis", "HasError": False, "Error": "", "Message": ""},
	//          "NewOrder": {
	//              "created": 1505531577,
	//              "type": 0,
	//              "order_type": 0,
	//              "status_type": 0,
	//              "amount": 0.01,
	//              "price": 10000,
	//              "stop": 0,
	//              "id": 9244416,
	//              "initialAmount": None,
	//          },
	//      }
	//      fetchOrder, fetchOpenOrders
	//      {
	//          "pair": "BtcNis",
	//          "status": "Completed",
	//          "created": 1535555837,
	//          "type": 0,
	//          "order_type": 0,
	//          "amount": 0.00000000,
	//          "price": 120000.00000000,
	//          "stop": 0,
	//          "id": 10555173,
	//          "initialAmount": 2.00000000
	//      }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var orderUnified any = nil
	var isNewOrder bool = false
	if InOp(order, "NewOrder") {
		orderUnified = GetValue(order, "NewOrder")
		isNewOrder = true
	} else {
		orderUnified = order
	}
	var id *string = this.SafeString(orderUnified, "id")
	var symbol *string = this.SafeSymbol(nil, market)
	var timestamp *int64 = this.SafeIntegerProduct(orderUnified, "created", 1000)
	// status field vary between responses
	// bit2c status type:
	// 0 = New
	// 1 = Open
	// 5 = Completed
	var status *string = nil
	if isNewOrder {
		var tempStatus *int64 = this.SafeInteger(orderUnified, "status_type")
		if (tempStatus != nil && *tempStatus == 0) || (tempStatus != nil && *tempStatus == 1) {
			status = SafeStringPtr("open")
		} else if tempStatus != nil && *tempStatus == 5 {
			status = SafeStringPtr("closed")
		}
	} else {
		var tempStatus *string = this.SafeString(orderUnified, "status")
		if (tempStatus != nil && *tempStatus == "New") || (tempStatus != nil && *tempStatus == "Open") {
			status = SafeStringPtr("open")
		} else if tempStatus != nil && *tempStatus == "Completed" {
			status = SafeStringPtr("closed")
		}
	}
	// bit2c order type:
	// 0 = LMT,  1 = MKT
	var typeVar *string = this.SafeString(orderUnified, "order_type")
	if typeVar != nil && *typeVar == "0" {
		typeVar = SafeStringPtr("limit")
	} else if typeVar != nil && *typeVar == "1" {
		typeVar = SafeStringPtr("market")
	}
	// bit2c side:
	// 0 = buy, 1 = sell
	var side *string = this.SafeString(orderUnified, "type")
	if side != nil && *side == "0" {
		side = SafeStringPtr("buy")
	} else if side != nil && *side == "1" {
		side = SafeStringPtr("sell")
	}
	var price *string = this.SafeString(orderUnified, "price")
	var amount *string = nil
	var remaining *string = nil
	if isNewOrder {
		amount = this.SafeString(orderUnified, "amount") // NOTE:'initialAmount' is currently not set on new order
		remaining = this.SafeString(orderUnified, "amount")
	} else {
		amount = this.SafeString(orderUnified, "initialAmount")
		remaining = this.SafeString(orderUnified, "amount")
	}
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          remaining,
		"cost":               nil,
		"trades":             nil,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}

