func (this *Bit2c) fetchDepositAddressBody(ch chan any, code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	if this.IsFiat(code) {
		panic(NotSupported(this.Id + " fetchDepositAddress() does not support fiat currencies"))
	}
	var request map[string]any = map[string]any{
		"Coin": currency["id"],
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostFundsAddCoinFundsRequest(this.Extend(request, params))).Raw))

	//
	//     {
	//         "address": "0xf14b94518d74aff2b1a6d3429471bcfcd3881d42",
	//         "hasTx": False
	//     }
	//
	ch <- this.ParseDepositAddress(response, currency)
	return nil
}
func (this *Bit2c) ParseDepositAddress(depositAddress any, optionalArgs ...any) any {
	//
	//     {
	//         "address": "0xf14b94518d74aff2b1a6d3429471bcfcd3881d42",
	//         "hasTx": False
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var address *string = this.SafeString(depositAddress, "address")
	this.CheckAddress(address)
	var code *string = this.SafeCurrencyCode(nil, currency)
	return map[string]any{
		"info":     depositAddress,
		"currency": code,
		"network":  nil,
		"address":  address,
		"tag":      nil,
	}
}
func (this *Bit2c) Nonce() any {
	return this.Milliseconds()
}
func (this *Bit2c) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), "rest")
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + "/" + this.ImplodeParams(path, params)
	var requestBody any = nil
	var requestHeaders any = nil
	if api == "public" {
		url += ".json"
	} else {
		this.CheckRequiredCredentials()
		// bit2c requires an increasing nonce per key
		var nonce any = this.IncrementingNonce()
		var query map[string]any = this.Extend(map[string]any{
			"nonce": nonce,
		}, params)
		var auth string = this.Urlencode(query)
		if method == "GET" {
			if len(query) > 0 {
				url += "?" + auth
			}
		} else {
			requestBody = auth
		}
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha512, "base64")
		requestHeaders = map[string]any{
			"Content-Type": "application/x-www-form-urlencoded",
			"key":          this.ApiKey,
			"sign":         signature,
		}
	}
	var bodyResult any = func() any {
		if requestBody == nil {
			return body
		}
		return requestBody
	}()
	var headersResult any = func() any {
		if requestHeaders == nil {
			return headers
		}
		return requestHeaders
	}()
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResult,
		"headers": headersResult,
	}
}
func (this *Bit2c) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//     { "error" : "please approve new terms of use on site." }
	//     { "error": "Please provide valid nonce in Request Nonce (1598218490) is not bigger than last nonce (1598218490)."}
	//     { "Error" : "No order found." }
	//
	var error *string = this.SafeString(response, "error")
	if error == nil {
		error = this.SafeString(response, "Error")
	}
	if error != nil {
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBit2c(userConfig map[string]any) *Bit2c {
	p := newBit2c()
	p.Init(userConfig)
	return p
}

func (this *Bit2c) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

